#include <iostream>

class Progress {
    int total_;
    int completed_{};
public:
    explicit Progress(int total) : total_{total < 0 ? 0 : total} {}
    bool advance(int pages)
    {
        if (pages < 0 || pages > total_ - completed_) return false;
        completed_ += pages;
        return true;
    }
    int completed() const { return completed_; }
    int remaining() const { return total_ - completed_; }
};

int main()
{
    Progress progress{10};
    std::cout << std::boolalpha << progress.advance(4) << ' '
              << progress.advance(8) << '\n';
    std::cout << progress.completed() << ' ' << progress.remaining() << '\n';
}
